<?php
/**
 * The inner pages: category, location category, service, town service and location pages.
 *
 * Each kind of page is an entry in its own post type, so its Elementor template and its ACF
 * field groups (acf-json/group_llp_cat_*, _svc_*, _loc_*) apply themselves. The list of post
 * types is page-post-types.json, generated by Copybot from wp/post-types.js: don't edit it on
 * a site.
 *
 * 1. A post type on the list that the site doesn't have is registered here, so a site can't
 *    be missing one. One the site already has (ACF, CPT UI, the theme) is left as it is.
 * 2. A page's URL is the path Copybot's page map gives it, held in the post meta _llp_path
 *    ("/services/patios", "/locations/romsey/patios"). WordPress can't build those nested
 *    paths across post types from its own settings, so the permalink is filtered to the path
 *    and a request for the path is answered with the entry. An entry with no path keeps the
 *    post type's ordinary URL.
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/** page-post-types.json: array( 'path_meta' => '_llp_path', 'post_types' => array( array( post_type, label, singular ), … ) ). */
function llp_page_types_config() {
	static $config = null;
	if ( null === $config ) {
		$raw    = file_get_contents( __DIR__ . '/page-post-types.json' );
		$config = $raw ? json_decode( $raw, true ) : array();
		if ( ! is_array( $config ) || empty( $config['post_types'] ) || ! is_array( $config['post_types'] ) ) {
			$config = array( 'path_meta' => '_llp_path', 'post_types' => array() );
		}
	}
	return $config;
}

/** The post type names: array( 'service-category', 'category-location', … ). */
function llp_page_post_types() {
	return array_values( wp_list_pluck( llp_page_types_config()['post_types'], 'post_type' ) );
}

function llp_page_path_meta() {
	$config = llp_page_types_config();
	return isset( $config['path_meta'] ) ? (string) $config['path_meta'] : '_llp_path';
}

/**
 * A path as it is stored: "/services/patios". Lower case words of letters, digits and
 * hyphens, a leading slash, no trailing one. Anything else is ''.
 */
function llp_page_clean_path( $path ) {
	if ( ! is_string( $path ) ) {
		return '';
	}
	$path = '/' . trim( strtolower( trim( $path ) ), '/' );
	return preg_match( '#^(/[a-z0-9]+(-[a-z0-9]+)*)+$#', $path ) ? $path : '';
}

/** The page map path of an entry, or '' when it has none. */
function llp_page_path( $post_id ) {
	return llp_page_clean_path( get_post_meta( $post_id, llp_page_path_meta(), true ) );
}

/** The entry a path belongs to (any status but the bin), or 0. The oldest wins when two share one. */
function llp_page_id_for_path( $path ) {
	$path  = llp_page_clean_path( $path );
	$types = llp_page_post_types();
	if ( '' === $path || ! $types ) {
		return 0;
	}
	$ids = get_posts(
		array(
			'post_type'        => $types,
			'post_status'      => 'any',
			'meta_key'         => llp_page_path_meta(),
			'meta_value'       => $path,
			'fields'           => 'ids',
			'numberposts'      => 1,
			'orderby'          => 'ID',
			'order'            => 'ASC',
			'suppress_filters' => true,
		)
	);
	return $ids ? (int) $ids[0] : 0;
}

/** For the status route: array( post type => 'site' (registered by the site) or 'plugin' (registered here) ). */
function llp_page_types_status() {
	$ours = isset( $GLOBALS['llp_page_types_registered'] ) ? $GLOBALS['llp_page_types_registered'] : array();
	$out  = array();
	foreach ( llp_page_post_types() as $type ) {
		$out[ $type ] = in_array( $type, $ours, true ) ? 'plugin' : ( post_type_exists( $type ) ? 'site' : 'missing' );
	}
	return $out;
}

// Late on init, after the site's own post types are registered
add_action(
	'init',
	function () {
		$registered = array();
		foreach ( llp_page_types_config()['post_types'] as $t ) {
			$type = $t['post_type'];
			if ( ! post_type_exists( $type ) ) {
				register_post_type(
					$type,
					array(
						'label'        => $t['label'],
						'labels'       => array(
							'name'          => $t['label'],
							'singular_name' => $t['singular'],
							'add_new_item'  => 'Add ' . $t['singular'],
							'edit_item'     => 'Edit ' . $t['singular'],
						),
						'public'       => true,
						'show_in_rest' => true,
						'hierarchical' => false,
						'has_archive'  => false,
						'menu_icon'    => 'dashicons-media-text',
						'supports'     => array( 'title', 'editor', 'thumbnail', 'revisions', 'custom-fields' ),
						'rewrite'      => array( 'slug' => $type, 'with_front' => false ),
					)
				);
				$registered[] = $type;
			}
			// The REST API only carries post meta for a post type that supports custom fields
			add_post_type_support( $type, 'custom-fields' );
			register_post_meta(
				$type,
				llp_page_path_meta(),
				array(
					'type'              => 'string',
					'single'            => true,
					'show_in_rest'      => true,
					'sanitize_callback' => 'llp_page_clean_path',
					'auth_callback'     => function () {
						return current_user_can( 'edit_pages' );
					},
				)
			);
		}
		$GLOBALS['llp_page_types_registered'] = $registered;
		// A post type registered here for the first time needs the rewrite rules rebuilt once
		$key = implode( ',', $registered );
		if ( get_option( 'llp_page_types_registered', '' ) !== $key ) {
			update_option( 'llp_page_types_registered', $key );
			flush_rewrite_rules( false );
		}
	},
	99
);

// The permalink is the page map path
add_filter(
	'post_type_link',
	function ( $link, $post ) {
		if ( ! is_object( $post ) || ! in_array( $post->post_type, llp_page_post_types(), true ) ) {
			return $link;
		}
		$path = llp_page_path( $post->ID );
		return '' === $path ? $link : home_url( user_trailingslashit( $path ) );
	},
	20,
	2
);

// A request for a page map path is answered with its entry, whatever WordPress made of the URL
add_filter(
	'request',
	function ( $query_vars ) {
		if ( is_admin() || ! isset( $GLOBALS['wp'] ) || ! is_object( $GLOBALS['wp'] ) || empty( $GLOBALS['wp']->request ) ) {
			return $query_vars;
		}
		$id = llp_page_id_for_path( '/' . $GLOBALS['wp']->request );
		if ( ! $id ) {
			return $query_vars;
		}
		$out = array(
			'post_type' => get_post_type( $id ),
			'p'         => $id,
		);
		if ( is_array( $query_vars ) && isset( $query_vars['preview'] ) ) {
			$out['preview'] = $query_vars['preview'];
		}
		return $out;
	}
);
